/**
 * Labyrinth 1.1 backup & recovery status (`D4`, `Spec §6.7`).
 */
public struct LabyrinthBackupStatus {
    public var backupEnabled: Bool
    /**
     * True once this device has opened or created the account's archive on the server: a
     * session verified the mailbox Space with its device and epoch records. Never reset.
     * Until then `epoch_seq` and `active_device_ids` are first-open placeholders.
     */
    public var archiveEstablished: Bool
    public var mailboxSpaceUri: String
    public var hasRecoveryCode: Bool
    public var hasPasskeyPrf: Bool
    /**
     * A rotation minted a replacement code that still needs to be saved or
     * replaced by the account owner. Durable across app restarts.
     */
    public var recoveryNeedsAttention: Bool
    /**
     * Identifies the recovery receipt minted on this device. Zero identifies older state.
     */
    public var recoveryGeneration: UInt64
    public var epochSeq: UInt64
    public var activeDeviceIds: [String]
    /**
     * Advisory only: this restored keychain/passkey method passed its
     * client-clock freshness window but remains valid until rotation.
     */
    public var recoveryMethodStale: Bool
    /**
     * Recovery/device members unexpectedly excluded by the latest rotation.
     */
    public var rotationExclusions: [LabyrinthRotationExclusion]
    /**
     * Epoch head durably queued for PDS + directory publication.
     */
    public var pendingDirectoryEpoch: UInt64?
    /**
     * True after a publication retry failed; archive items remain queued.
     */
    public var directoryPublicationStalled: Bool
    /**
     * Number of app-start/sync publication attempts observed by this device.
     */
    public var directoryPublicationRetryCount: UInt64
    /**
     * Last retry failure, cleared once both directory publications succeed.
     */
    public var directoryPublicationError: String?

    /// Default memberwise initializers are never public by default, so we
    /// declare one manually.
    public init(backupEnabled: Bool,
                /* 
                    * True once this device has opened or created the account's archive on the server: a
                    * session verified the mailbox Space with its device and epoch records. Never reset.
                    * Until then `epoch_seq` and `active_device_ids` are first-open placeholders.
                    */ archiveEstablished: Bool = false, mailboxSpaceUri: String, hasRecoveryCode: Bool, hasPasskeyPrf: Bool,
                /* 
                    * A rotation minted a replacement code that still needs to be saved or
                    * replaced by the account owner. Durable across app restarts.
                    */ recoveryNeedsAttention: Bool,
                /* 
                    * Identifies the recovery receipt minted on this device. Zero identifies older state.
                    */ recoveryGeneration: UInt64 = UInt64(0), epochSeq: UInt64, activeDeviceIds: [String],
                /* 
                    * Advisory only: this restored keychain/passkey method passed its
                    * client-clock freshness window but remains valid until rotation.
                    */ recoveryMethodStale: Bool,
                /* 
                    * Recovery/device members unexpectedly excluded by the latest rotation.
                    */ rotationExclusions: [LabyrinthRotationExclusion],
                /* 
                    * Epoch head durably queued for PDS + directory publication.
                    */ pendingDirectoryEpoch: UInt64?,
                /* 
                    * True after a publication retry failed; archive items remain queued.
                    */ directoryPublicationStalled: Bool,
                /* 
                    * Number of app-start/sync publication attempts observed by this device.
                    */ directoryPublicationRetryCount: UInt64,
                /* 
                    * Last retry failure, cleared once both directory publications succeed.
                    */ directoryPublicationError: String?)
    {
        self.backupEnabled = backupEnabled
        self.archiveEstablished = archiveEstablished
        self.mailboxSpaceUri = mailboxSpaceUri
        self.hasRecoveryCode = hasRecoveryCode
        self.hasPasskeyPrf = hasPasskeyPrf
        self.recoveryNeedsAttention = recoveryNeedsAttention
        self.recoveryGeneration = recoveryGeneration
        self.epochSeq = epochSeq
        self.activeDeviceIds = activeDeviceIds
        self.recoveryMethodStale = recoveryMethodStale
        self.rotationExclusions = rotationExclusions
        self.pendingDirectoryEpoch = pendingDirectoryEpoch
        self.directoryPublicationStalled = directoryPublicationStalled
        self.directoryPublicationRetryCount = directoryPublicationRetryCount
        self.directoryPublicationError = directoryPublicationError
    }
}

extension LabyrinthBackupStatus: Equatable, Hashable {
    public static func == (lhs: LabyrinthBackupStatus, rhs: LabyrinthBackupStatus) -> Bool {
        if lhs.backupEnabled != rhs.backupEnabled {
            return false
        }
        if lhs.archiveEstablished != rhs.archiveEstablished {
            return false
        }
        if lhs.mailboxSpaceUri != rhs.mailboxSpaceUri {
            return false
        }
        if lhs.hasRecoveryCode != rhs.hasRecoveryCode {
            return false
        }
        if lhs.hasPasskeyPrf != rhs.hasPasskeyPrf {
            return false
        }
        if lhs.recoveryNeedsAttention != rhs.recoveryNeedsAttention {
            return false
        }
        if lhs.recoveryGeneration != rhs.recoveryGeneration {
            return false
        }
        if lhs.epochSeq != rhs.epochSeq {
            return false
        }
        if lhs.activeDeviceIds != rhs.activeDeviceIds {
            return false
        }
        if lhs.recoveryMethodStale != rhs.recoveryMethodStale {
